using System;
using Outbreak.Contracts;
using Outbreak.Core;
using Outbreak.Persistence;
public static partial class Program
{
    private static void CheckHouseholdFoodCases()
    {
        Check("Household food targets count away residents and balance one total across boxes",()=>{
            World world=EncounterScenarios.HouseholdFoodTargetsTest();string before=State(world);HouseholdFoodSupply row=world.HouseholdFoodSupplies(183);Require(row.Residents==2 && row.RequestedMeals==6 && row.BoxTarget==6 && row.AutomaticBoxes==2 && row.UnallocatedMeals==0,"Household duplicated target or omitted away resident.");Require(world.EffectiveFoodReserve(world.StorageBoxAt(4,3))==3 && world.EffectiveFoodReserve(world.StorageBoxAt(2,7))==3 && row.ReserveDeficit==3,"Automatic boxes did not receive balanced independent shares.");Require(world.HouseholdFoodSupplies(192).Residents==1 && world.HouseholdFoodSupplies(192).RequestedMeals==3,"Visiting courier counted toward another household.");Require(State(world)==before,"Household food read model changed world state.");Require(world.TryAssignHouse(1,13,3) && world.HouseholdFoodSupplies(183).RequestedMeals==3 && world.HouseholdFoodSupplies(192).RequestedMeals==6,"Household targets failed to follow reassignment.");Require(world.EffectiveFoodReserve(world.StorageBoxAt(4,3))==2 && world.EffectiveFoodReserve(world.StorageBoxAt(2,7))==1,"Odd meal remainder was not assigned in stable cell order.");
        });
        Check("Manual box overrides remain protected and insufficient capacity is visible",()=>{
            World world=EncounterScenarios.HouseholdFoodTargetsTest();Require(world.TrySetStorageFoodReserve(4,3,6) && world.StorageBoxAt(4,3).foodReserve==6,"Explicit default reserve could not override household allocation.");Require(world.EffectiveFoodReserve(world.StorageBoxAt(4,3))==6 && world.EffectiveFoodReserve(world.StorageBoxAt(2,7))==0,"Manual reserve was duplicated by automatic boxes.");Require(world.TrySetStorageFoodReserve(4,3,0) && world.EffectiveFoodReserve(world.StorageBoxAt(4,3))==0 && world.EffectiveFoodReserve(world.StorageBoxAt(2,7))==6,"Explicit restocking-off box reentered automatic targets.");Require(world.TryUseHouseholdFoodTarget(4,3) && world.EffectiveFoodReserve(world.StorageBoxAt(4,3))==3,"Automatic target could not be restored.");SaveDocument saved=world.Capture();Array.Find(saved.map.storageBoxes,box=>box.x==2 && box.y==7).capacity=1;world=World.Restore(saved);Require(world.EffectiveFoodReserve(world.StorageBoxAt(2,7))==1 && world.EffectiveFoodReserve(world.StorageBoxAt(4,3))==5,"Capacity-capped share was not redistributed.");world.TrySetStorageFoodReserve(4,3,0);Require(world.HouseholdFoodSupplies(183).BoxTarget==1 && world.HouseholdFoodSupplies(183).UnallocatedMeals==5,"Storage shortage was silently hidden.");Require(world.TrySetHouseholdMealsPerResident(183,0) && world.EffectiveFoodReserve(world.StorageBoxAt(2,7))==1 && world.EffectiveFoodReserve(world.StorageBoxAt(4,3))==0,"Disabling policy lost original box targets or explicit off override.");
        });
        Check("Resident restocking uses household reserves and resumes exactly from saves",()=>{
            World world=EncounterScenarios.StorageRestockTest();world.TryAssignHouse(0,3,3);Require(world.TrySetHouseholdMealsPerResident(27,8),"Could not enable resident food target.");World copy=Documents.ParseSave(State(world));for(int i=0;i<1000 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)<8;i++){world.Step();copy.Step();Require(State(world)==State(copy),"Household-target restocking diverged after save.");}Require(StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)>=8 && world.EffectiveFoodReserve(world.StorageBoxAt(4,3))==8,"Resident kept fixed six-meal goal instead of household target.");
        });
        Check("Delivery pickup rechecks the donor household reserve after a target increase",()=>{
            World world=EncounterScenarios.SupplyDeliveryTest();int id;Require(world.TrySpawn(Species.Human,11,5,out id) && world.TryAssignHouse(1,11,5),"Could not arrange donor resident.");world.TrySetHouseholdMealsPerResident(72,3);world.Step();Require(world.ActorAt(0).restockSourceBox==73,"Known donor job did not start.");Require(world.TrySetHouseholdMealsPerResident(72,12),"Could not raise donor household target while courier travelled.");for(int i=0;i<200;i++){world.Step();Require(StorageRules.Count(world.StorageBoxAt(12,3),InventoryItem.Food)==12,"Courier took food reserved by the donor household.");}Require(world.EffectiveFoodReserve(world.StorageBoxAt(12,3))==12 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==0,"Donor household target did not protect actual inventory.");
        });
        Check("Household policy persistence is detached versioned and strictly validated",()=>{
            World world=EncounterScenarios.HouseholdFoodTargetsTest();Require(State(Documents.ParseSave(State(world)))==State(world),"Household food settings changed after JSON round trip.");SaveDocument detached=world.Capture();detached.householdFoodTargets[0].mealsPerResident=12;Require(world.HouseholdMealsPerResident(183)==3,"Save policy records escaped by reference.");string before=State(world);Require(!world.TrySetHouseholdMealsPerResident(0,3) && !world.TrySetHouseholdMealsPerResident(183,13) && !world.TrySetHouseholdMealsPerResident(183,-1) && State(world)==before,"Invalid policy edit changed world.");Action<Action<SaveDocument>> bad=change=>{SaveDocument saved=world.Capture();change(saved);Reject(()=>World.Restore(saved));};bad(s=>s.rulesVersion=EncounterRules.CourierAssignmentsVersion);bad(s=>s.householdFoodTargets[0].mealsPerResident=0);bad(s=>s.householdFoodTargets[0].houseId=0);bad(s=>s.householdFoodTargets=new[]{s.householdFoodTargets[0],s.householdFoodTargets[0]});bad(s=>s.householdFoodTargets=new HouseholdFoodTargetDocument[0]);SaveDocument old=EncounterScenarios.StorageSupplyTest().Capture();old.rulesVersion=EncounterRules.CourierAssignmentsVersion;World legacy=World.Restore(old);Require(!legacy.HouseholdFoodTargetsEnabled && legacy.CourierAssignmentsEnabled && !legacy.TrySetHouseholdMealsPerResident(27,3) && legacy.EffectiveFoodReserve(legacy.StorageBoxAt(4,3))==6,"Earlier rules gained automatic household food targets.");
        });
        Check("Household reserve demand follows conversion and flags empty houses with away members",()=>{
            World world=EncounterScenarios.HouseholdFoodTargetsTest();SaveDocument saved=world.Capture();saved.actors[1].turnAtTick=1;world=World.Restore(saved);Require(world.HouseholdFoodSupplies(183).RequestedMeals==6,"Infected living member disappeared from demand before conversion.");world.Step();Require(world.HouseholdFoodSupplies(183).RequestedMeals==3,"Converted resident still raised household demand.");world=EncounterScenarios.HouseholdFoodTargetsTest();world.TryAssignHouse(1,13,3);SaveDocument away=world.Capture();away.actors[1].x=12;away.actors[1].y=7;away.actors[1].shelterId=192;away.actors[1].shelterX=12;away.actors[1].shelterY=7;away.actors[1].shelterState=ShelterState.Inside;world=World.Restore(away);world.TrySetStorageFoodReserve(4,3,0);HouseholdFoodSupply food=world.HouseholdFoodSupplies(183);ShelterSupplyOverview supply=SupplyRoom(world,183);Require(food.Residents==1 && supply.Occupants==0 && supply.AssignedResidents==1 && supply.NeedsAttention && supply.Status=="BELOW RESERVE","Away household shortage was hidden as an unused house.");world.TrySetStorageFoodReserve(2,7,0);supply=SupplyRoom(world,183);Require(supply.ReserveDeficit==0 && supply.UnallocatedMeals==3 && supply.NeedsAttention && supply.Status=="BELOW RESERVE","Unallocated demand disappeared when no automatic box could cover it.");
        });
    }
}
